t = int(input())
for i in range(t):
	(m, n) = map(int, input().split())
	(b1, b2) = (bin(m)[2:], bin(n)[2:])
	if len(b1) != len(b2):
		m = max(len(b1), len(b2))
		print(int('1' * m, 2))
	else:
		c = 0
		while c < len(b1) and b1[c] == b2[c]:
			c += 1
		ans = b1[:c] + '1' * (len(b1) - c)
		print(int(ans, 2))
